mapper.sql:
WHERE account.deleted_at IS NULL

    AND (
        account.email LIKE #{keywordPattern} ESCAPE '!'
        OR company.company_name LIKE #{keywordPattern} ESCAPE '!'

            OR company.business_number LIKE #{businessNumberPattern}

    )


    AND account.suspended_at IS NULL


    AND account.suspended_at IS NOT NULL


    AND account.role = #{role}




        AND account.password_hash IS NOT NULL


        AND EXISTS (
            SELECT 1
            FROM account_oauth_identity identity
            WHERE identity.account_id = account.id
              AND identity.provider = #{loginMethod}
        )

mapper.select:
SELECT COUNT(*)
FROM partner_recruitment
WHERE account_id = #{accountId}

SELECT COUNT(*)
FROM partner_recruitment
WHERE account_id = #{accountId}
  AND closed_at IS NULL
  AND recruitment_deadline >= #{today}

SELECT COUNT(*)
FROM partner_proposal
WHERE proposer_account_id = #{accountId}

SELECT COUNT(*)
FROM account_session
WHERE account_id = #{accountId}
  AND expires_at > #{now}

mapper.update:
UPDATE account
SET suspended_at = #{suspendedAt}
WHERE id = #{accountId}
  AND deleted_at IS NULL
